import{_ as t,o,c as a,a3 as d}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Live Chat (developer)","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Live Chat (developer) | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/live-chat"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Live Chat (developer) | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/live-chat"}]]},"headers":[],"relativePath":"developer-guide/live-chat.md","filePath":"developer-guide/live-chat.md","lastUpdated":1794259478000}'),i={name:"developer-guide/live-chat.md"};function c(s,e,n,r,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="live-chat-developer" tabindex="-1">Live Chat (developer) <a class="header-anchor" href="#live-chat-developer" aria-label="Permalink to &quot;Live Chat (developer)&quot;">​</a></h1><p>Free Communication module (<code>live-chat</code> <strong>2.1.0</strong>). Public widget traffic resolves the workspace by widget <code>public_key</code> (central/web routes), initializes tenancy, checks entitlement, then ends tenancy — same pattern as custom Lead webhooks.</p><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Auth</th></tr></thead><tbody><tr><td><code>GET/POST /api/public/live-chat/{publicKey}/…</code></td><td>Widget key + visitor Bearer session token (SHA-256 hashed at rest)</td></tr><tr><td><code>/api/tenant/v1/live-chat/…</code></td><td><code>auth:tenant-api</code> + <code>module:live-chat</code> + Spatie <code>can:</code></td></tr><tr><td><code>public/widgets/live-chat.js</code></td><td>Static embed script (<code>data-key</code>, <code>data-api-base</code>) — Tawk-style FAB/panel in a <strong>Shadow DOM</strong> host</td></tr><tr><td>SPA <code>/live-chat</code></td><td>Agent desk tabs: Overview / Inbox / Live visitors</td></tr><tr><td>SPA <code>/settings?tab=live-chat</code></td><td>Widget / departments / canned replies / proactive rules (<code>live-chat.manage</code>)</td></tr></tbody></table><p>Throttle: <code>live-chat-widget</code> (60/min by IP + key) and <code>live-chat-widget-session</code> (10/min for session create); disabled in testing. CSRF excepted for <code>api/public/live-chat/*</code>.</p><p><strong>CORS:</strong> <code>LiveChatPublicCors</code> reflects <code>Origin</code> for credential-less public widget paths only (does not open the rest of the API).</p><p><strong>Public DTOs:</strong> Visitor responses use <code>LiveChatPublicConversationResource</code> / <code>LiveChatPublicMessageResource</code> — uuid/status/body/direction/attachment meta/<code>agent_name</code> (agent rows; workspace user Name, no email/id)/timestamps only (no assignee, Lead, visitor IP, sender email, or <code>direction=note</code>).</p><p><strong>Sessions:</strong> Expire after 7 days from creation. Regenerating the public key (or deactivating the widget / cancelling the module) revokes all visitor session hashes. Retention: <code>live-chat:purge-visitors --days=90</code> (daily). Banned visitors (<code>is_banned</code>) and <strong>banned IPs</strong> (<code>live_chat_banned_ips</code>, SHA-256 hash per tenant) cannot create sessions or send messages.</p><p><strong>Embed resume (1.4.1+):</strong> The widget persists <code>session_token</code> / conversation hints in <code>localStorage</code> keyed by public key. On load it validates via <code>POST …/heartbeat</code> (which returns <code>open_conversation_uuid</code> when an open thread exists), then hydrates both visitor and agent messages. Host-page CSS cannot restyle the pre-chat form because UI lives in Shadow DOM with explicit dark labels/input colors.</p><h2 id="branding-hours-offline-presence" tabindex="-1">Branding, hours, offline, presence <a class="header-anchor" href="#branding-hours-offline-presence" aria-label="Permalink to &quot;Branding, hours, offline, presence&quot;">​</a></h2><p>Widget settings store <code>primary_color</code>, <code>launcher_text</code>, <code>position</code>, <code>header_title</code>, <code>logo_url</code>, <code>offline_*</code>, <code>business_hours</code>, <code>email_notify_agents</code>, <code>idle_minutes</code>, <code>email_transcript_on_close</code>, <code>csat_enabled</code>, <code>default_department_id</code>, <code>suggested_replies</code>, <code>show_powered_by</code>, <code>agent_display_name</code>. Bootstrap returns branding plus <code>within_hours</code> / <code>accepting_live</code>, <code>csat_enabled</code>, active <code>departments</code>, <code>default_department_id</code>, and optional Reverb public hints. Outside hours (or inactive accepting), visitors leave offline messages when <code>offline_enabled</code>.</p><h3 id="pre-chat-identity-2-1-0" tabindex="-1">Pre-chat identity (2.1.0+) <a class="header-anchor" href="#pre-chat-identity-2-1-0" aria-label="Permalink to &quot;Pre-chat identity (2.1.0+)&quot;">​</a></h3><p>Public <code>POST …/conversations</code> and offline leave-a-message require <code>name</code>, <code>email</code>, <code>phone</code>, and <code>department_id</code> when the workspace has active Live Chat departments (otherwise department falls back to widget <code>default_department_id</code>). Visitor <code>phone</code> is stored on <code>live_chat_visitors</code>. Embed <code>?v=2.1.0</code> always collects these fields before Start / Leave a message.</p><h3 id="heartbeat-intel-1-8-0" tabindex="-1">Heartbeat intel (1.8.0+) <a class="header-anchor" href="#heartbeat-intel-1-8-0" aria-label="Permalink to &quot;Heartbeat intel (1.8.0+)&quot;">​</a></h3><p><code>POST …/heartbeat</code> (Bearer session) accepts optional <code>page_url</code>, <code>page_title</code>, <code>referrer</code>, <code>screen</code>, <code>language</code>. The presence service updates:</p><ul><li>Rolling <strong>page history</strong> (path changes increment <code>pages_viewed</code>)</li><li>UA-derived <strong>browser</strong>, <strong>os</strong>, <strong>device_type</strong></li><li>CDN/request geo: <strong>country_code</strong>, <strong>city</strong>, <strong>region</strong></li><li>First-page <strong>landing_url</strong> and <strong>utm_</strong>* parsed from the landing URL query string</li><li><strong>session_started_at</strong>, <strong>visit_count</strong>, <strong>client_id</strong> (session create can pass <code>client_id</code> to merge returning browsers)</li></ul><p>Tenant <code>GET …/visitors/live</code> and conversation visitor payloads expose these fields for the desk. Presence broadcasts throttle on the inbox channel as <code>LiveChatVisitorPresence</code>.</p><h2 id="public-identify-1-9-0" tabindex="-1">Public identify (1.9.0+) <a class="header-anchor" href="#public-identify-1-9-0" aria-label="Permalink to &quot;Public identify (1.9.0+)&quot;">​</a></h2><p><code>POST …/identify</code> (Bearer session) accepts at least one of: <code>name</code>, <code>email</code>, <code>user_id</code> (stored as <code>external_user_id</code>), <code>attributes</code> (object, max 20 keys → <code>custom_attributes</code>). Returns visitor uuid + identity fields. Use after login on customer sites so agents see CRM ids without pre-chat.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Agent <code>POST …/messages</code> accepts <code>as_note=true</code> (<code>LiveChatMessageDirectionEnum::Note</code>). Notes are returned on tenant message lists and never on public visitor polls or broadcast visitor payloads.</p><p><strong>Visitor notes (2.0.0):</strong> Tenant CRUD on <code>live_chat_visitor_notes</code> — internal notes keyed to <code>visitor_id</code> (not the same as thread <code>direction=note</code> messages). List: <code>live-chat.view</code>; write: <code>live-chat.manage</code>.</p><h2 id="realtime" tabindex="-1">Realtime <a class="header-anchor" href="#realtime" aria-label="Permalink to &quot;Realtime&quot;">​</a></h2><p>Agent channels (distinct from Team Chat):</p><ul><li><code>private-tenant.{tenantId}.live-chat.inbox</code></li><li><code>private-tenant.{tenantId}.live-chat.conversation.{uuid}</code></li></ul><p>Visitor public channel: <code>live-chat.visitor.{uuid}</code> (UUID secrecy). Events: <code>LiveChatMessageSent</code>, <code>LiveChatConversationUpdated</code>, <code>LiveChatVisitorPresence</code>, <code>LiveChatTyping</code>, <code>LiveChatInvite</code> (<code>ShouldBroadcastNow</code>, soft-failed on send/open/close paths).</p><p>Agent <code>POST …/visitors/{id}/open-chat</code> with optional <code>body</code> opens/assigns and invites the embed. <strong>Proactive rules</strong> use the same invite path via <code>LiveChatProactiveScanService</code> + <code>live-chat:scan-proactive</code> (scheduled every minute). Embed hydrates when heartbeat sees <code>open_conversation_uuid</code>, subscribes to the visitor channel as soon as a session exists, and auto-opens on invite. Embed keeps short-poll fallback; send lock + hydrate-before-retry on Retry. Typing also has HTTP endpoints: public + tenant <code>POST …/typing</code>. Settings embed snippet includes <code>?v=</code> cache-bust (<code>LiveChatWidgetService::WidgetScriptVersion</code> = <strong><code>2.1.0</code></strong>).</p><h2 id="csat-and-transcript-2-0-0" tabindex="-1">CSAT and transcript (2.0.0) <a class="header-anchor" href="#csat-and-transcript-2-0-0" aria-label="Permalink to &quot;CSAT and transcript (2.0.0)&quot;">​</a></h2><ul><li>Public <code>POST …/conversations/{uuid}/csat</code> — <code>score</code> 1–5, optional <code>comment</code> (max 2000); conversation must be <strong>closed</strong> and owned by the visitor; respects widget <code>csat_enabled</code>.</li><li>On agent close, when <code>email_transcript_on_close</code> is true and the visitor has email, <code>LiveChatTranscriptMail</code> is queued (soft-fail does not block close).</li></ul><h2 id="soft-leads-help-desk" tabindex="-1">Soft Leads / Help Desk <a class="header-anchor" href="#soft-leads-help-desk" aria-label="Permalink to &quot;Soft Leads / Help Desk&quot;">​</a></h2><p><code>PATCH …/conversations/{id}</code> with <code>lead_id</code> calls <code>LiveChatConversationService::linkLead</code>. Requires Leads entitled; null unlinks.</p><p><code>POST …/conversations/{id}/escalate</code> creates a Help Desk ticket (<code>source: live-chat</code>) when Help Desk is entitled and sets <code>help_desk_ticket_id</code>. Escalation transcript omits notes.</p><h2 id="canned-replies-departments-proactive-rules" tabindex="-1">Canned replies, departments, proactive rules <a class="header-anchor" href="#canned-replies-departments-proactive-rules" aria-label="Permalink to &quot;Canned replies, departments, proactive rules&quot;">​</a></h2><p>Tenant CRUD under <code>/live-chat/canned-replies</code>, <code>/live-chat/departments</code>, and <code>/live-chat/proactive-rules</code> (<code>manage</code> writes, <code>view</code> lists proactive rules).</p><p>Proactive rule fields: <code>widget_id</code>, <code>name</code>, <code>is_active</code>, optional <code>path_contains</code>, <code>min_dwell_seconds</code>, <code>min_pages_viewed</code>, <code>message</code>, <code>cooldown_minutes</code>. Per-visitor cooldown state lives in <code>proactive_cooldowns</code> JSON on the visitor row.</p><h2 id="automation" tabindex="-1">Automation <a class="header-anchor" href="#automation" aria-label="Permalink to &quot;Automation&quot;">​</a></h2><p>Wired triggers: <code>live_chat.conversation_opened</code>, <code>live_chat.message_inbound</code>, <code>live_chat.conversation_closed</code>, <strong><code>live_chat.proactive_invite_sent</code></strong> — fan-out via <code>IntegrationEventDispatcher</code>.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Do <strong>not</strong> fan out to every user with <code>live-chat.view</code>. Recipients are members of the conversation’s Live Chat department (visitor-selected or widget default) who also have <code>live-chat.reply</code>, capped at 20. Empty roster skips notify (<code>live-chat.notify_skipped_empty_roster</code>). Intake payloads include <code>visitor_name</code>, <code>visitor_email</code>, <code>visitor_phone</code>, and <code>department_name</code>. Keep production workers out of Live Chat departments even if Staff still has Live Chat permissions.</p><table tabindex="0"><thead><tr><th>Event</th><th>Recipients</th><th>Channels</th></tr></thead><tbody><tr><td>First visitor message (unassigned)</td><td>Department agents</td><td><code>database</code> + <code>broadcast</code> + FCM; optional mail when <code>email_notify_agents</code></td></tr><tr><td>Later visitor messages while unassigned</td><td>Department agents</td><td><code>database</code> + <code>broadcast</code></td></tr><tr><td>Visitor messages after assign</td><td>Assignee only</td><td><code>database</code> + <code>broadcast</code></td></tr><tr><td>First agent reply</td><td>Auto-assigns that agent; <code>live-chat.assigned</code></td><td>FCM + in-app</td></tr><tr><td>Idle (<code>idle_minutes</code>, default 5; <code>0</code> = off)</td><td>Department minus assignee</td><td>FCM + in-app once (<code>live-chat.idle</code>); <code>live-chat:scan-idle</code> every minute</td></tr></tbody></table><p>Inbox Reverb conversation list updates remain separate from notification wake-ups. Types: <code>live-chat.inbound</code>, <code>live-chat.assigned</code>, <code>live-chat.idle</code>.</p><h2 id="scheduler" tabindex="-1">Scheduler <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;Scheduler&quot;">​</a></h2><p>Registered in <code>routes/console.php</code> (onOneServer):</p><ul><li><code>live-chat:purge-visitors --days=90</code> (daily)</li><li><code>live-chat:scan-idle</code> (every minute)</li><li><strong><code>live-chat:scan-proactive</code></strong> (every minute)</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Pest: <code>tests/Feature/Tenant/LiveChat/</code> (identify, intel heartbeat, proactive scan, CSAT, IP ban, visitor notes, transcript mail). Playwright: <code>npm run test:e2e:live-chat</code>.</p><p>Production readiness: <a href="/deployment/live-chat-production-readiness">1.0.1 baseline</a> · <a href="/deployment/live-chat-1-5-0-production-readiness">1.5.0 / 1.5.1 send resilience + typing</a> · <a href="/deployment/live-chat-2-0-0-production-readiness">2.0.0 milestone</a> · <a href="/deployment/live-chat-2-1-0-production-readiness"><strong>2.1.0 current</strong></a>.</p>',47)])])}const v=t(i,[["render",c]]);export{u as __pageData,v as default};
